package it.frociart.app;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
public final class PostTestCorpusTests {
 static String read(Path path)throws Exception{return new String(Files.readAllBytes(path),StandardCharsets.UTF_8);}static String hash(String text)throws Exception{StringBuilder b=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)))b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}
 static String mapping(FlowSourceText text)throws Exception{StringBuilder b=new StringBuilder();for(FlowSourceText.Line line:text.lines){b.append(line.number).append(',').append(line.start).append(',').append(line.length);for(FlowSourceText.Origin o:line.origins)b.append('|').append(o.functionId==null?"":o.functionId).append(':').append(o.nodeId);b.append('\n');}return hash(b.toString());}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),assets=Paths.get(args[1]);List<Path> files=new ArrayList<>();try(DirectoryStream<Path> stream=Files.newDirectoryStream(root.resolve("fixtures"),"*.frociart")){for(Path f:stream)files.add(f);}Collections.sort(files);List<String> rows=new ArrayList<>();int programs=0,invalid=0;for(Path file:files){String name=file.getFileName().toString().replace(".frociart","");FlowModel.Document d=FlowCodec.decode(read(file));FlowSource.Program p=FlowSource.compile(d);if(!p.canGenerate()){for(FlowSourceTarget target:FlowSourceTarget.ALL){boolean rejected=false;try{target.generate(p,read(assets.resolve(target.runtime)));}catch(IllegalArgumentException error){rejected=true;}if(!rejected)throw new AssertionError("Invalid graph exported: "+name+" / "+target.id);}invalid++;continue;}String before=FlowCodec.encode(d),className="Case"+programs;for(FlowSourceTarget target:FlowSourceTarget.ALL){String runtime=read(assets.resolve(target.runtime));FlowSourceText source=target==FlowSourceTarget.JAVA?FlowJava.generate(p,runtime,className):target==FlowSourceTarget.CSHARP?FlowCSharp.generate(p,runtime,className):target.generate(p,runtime);if(!before.equals(FlowCodec.encode(d)))throw new AssertionError("Generation modified document");for(FlowSource.Scope scope:p.scopes)for(FlowSource.Block block:scope.blocks)if(source.forBlock(scope.id,block.id).isEmpty())throw new AssertionError("Missing block mapping");rows.add(name+"\t"+target.id+"\t"+hash(source.text)+"\t"+mapping(source));}FlowSourceText planText=FlowCodeTemplate.create("Piano","custom","txt","","{% macro walk items %}{% for s in items %}{{ s.kind }} {{ s.loop }} {{ s.postTest }} {{ s.loopOnTrue }} {{ s.block.id }} {{ s.entryBlock.id }}\n{% render walk s.body %}{% render walk s.otherwise %}{% endfor %}{% endmacro %}{% for scope in program.scopes %}{{ scope.structured }}\n{% render walk scope.statements %}{% endfor %}").generate(p,null);rows.add(name+"\tplan\t"+hash(planText.text)+"\t"+mapping(planText));programs++;}List<String> expected=Files.readAllLines(root.resolve("pc-mapping.tsv"),StandardCharsets.UTF_8);if(!expected.equals(rows)){for(int i=0;i<Math.min(expected.size(),rows.size());i++)if(!expected.get(i).equals(rows.get(i)))throw new AssertionError("Text/mapping mismatch: "+rows.get(i)+" expected "+expected.get(i));throw new AssertionError("Count differs");}Files.write(root.resolve("android-mapping.tsv"),rows,StandardCharsets.UTF_8);System.out.println("POST_TEST_CORPUS_ANDROID PASS programs="+programs+" invalid="+invalid+" matches="+rows.size());}
}
